typescript.solution:
class DictNode {
  children = new Map<string, DictNode>()
  isWord = false
}

class WordDictionary {
  private root = new DictNode()

  addWord(word: string): void {
    let node = this.root
    for (const ch of word) {
      if (!node.children.has(ch)) node.children.set(ch, new DictNode())
      node = node.children.get(ch)!
    }
    node.isWord = true
  }

  search(word: string): boolean {
    const go = (node: DictNode, i: number): boolean => {
      if (i === word.length) return node.isWord
      const ch = word[i]
      if (ch === '.') {
        for (const child of node.children.values()) if (go(child, i + 1)) return true
        return false
      }
      const next = node.children.get(ch)
      return next ? go(next, i + 1) : false
    }
    return go(this.root, 0)
  }
}
